github.cancel.js:
// Checks GitHub's runner stopped (cancelled) at every head until obid reruns them (the rerun
// route writes rerun-done here), green after: obid-spec's AUTOFIX-6 workflow.
const fs = require("fs");
const { execFileSync } = require("child_process");
const [what, ...args] = process.argv.slice(2);
const view = JSON.parse(execFileSync("node", ["pull-request.js", "view", ...args], { encoding: "utf8" }));
const cancelled = view.state === "OPEN" && !fs.existsSync("rerun-done");
if (what === "view") {
  if (cancelled) {
    view.statusCheckRollup = [{ __typename: "CheckRun", name: "test", status: "COMPLETED", conclusion: "CANCELLED" }];
    view.mergeStateStatus = "UNSTABLE";
  }
  process.stdout.write(JSON.stringify(view) + "\n");
} else if (what === "failed") {
  process.stdout.write(JSON.stringify(cancelled ? [{ databaseId: 52 }] : []) + "\n");
} else if (what === "all") {
  process.stdout.write(JSON.stringify(cancelled ? [{ databaseId: 52, conclusion: "cancelled" }] : []) + "\n");
}
